package br.com.lealinfo.vidraceiro;
import android.content.Context;import android.util.AtomicFile;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.Files;import java.util.UUID;
/** Offline work drafts. Local UUIDs are explicitly distinct from authoritative PDV IDs. */
final class ProfessionalStore {
 final AtomicFile file;final Context context;JSONObject data;final java.util.Map<String,String> fingerprints=new java.util.HashMap<>();
 ProfessionalStore(Context c)throws Exception{context=c;file=new AtomicFile(new File(c.getFilesDir(),"professional.json"));if(file.getBaseFile().exists()||new File(file.getBaseFile().getPath()+".bak").exists())data=new JSONObject(new String(file.readFully(),StandardCharsets.UTF_8));else data=new JSONObject().put("schemaVersion",2).put("projects",new JSONArray()).put("clients",new JSONArray()).put("materials",new JSONArray()).put("suppliers",new JSONArray());remember();migrateLegacy();remember();}
 JSONArray list(String key){return data.optJSONArray(key);}
 JSONObject find(String key,String id){JSONArray a=list(key);for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o!=null&&id.equals(o.optString("id")))return o;}return null;}
 JSONObject add(String key)throws JSONException{JSONObject o=new JSONObject().put("id",UUID.randomUUID().toString()).put("createdAt",System.currentTimeMillis()).put("pdvId",JSONObject.NULL).put("syncState","LOCAL_DRAFT");list(key).put(o);return o;}
 private String fingerprint(JSONObject p)throws JSONException{JSONObject clone=new JSONObject(p.toString());clone.remove("revision");return clone.toString();}
 void remember()throws JSONException{JSONArray projects=list("projects");for(int i=0;i<projects.length();i++){JSONObject p=projects.getJSONObject(i);fingerprints.put(p.getString("id"),fingerprint(p));}}
 void save()throws Exception{JSONArray projects=list("projects");for(int i=0;i<projects.length();i++){JSONObject p=projects.getJSONObject(i);if(!fingerprint(p).equals(fingerprints.get(p.getString("id"))))p.put("revision",p.optInt("revision",0)+1);}byte[] bytes=data.toString().getBytes(StandardCharsets.UTF_8);FileOutputStream out=null;try{out=file.startWrite();out.write(bytes);file.finishWrite(out);remember();}catch(Exception e){if(out!=null)file.failWrite(out);throw e;}}
 private void migrateLegacy()throws Exception{if(data.optBoolean("legacyImported"))return;File[] dirs=new File(context.getFilesDir(),"images").listFiles(File::isDirectory);if(dirs!=null)for(File dir:dirs){File source=new File(dir,"draft.json");if(!source.exists())continue;try{JSONObject old=new JSONObject(new String(Files.readAllBytes(source.toPath()),StandardCharsets.UTF_8));String id=old.optString("id",dir.getName());if(find("projects",id)!=null)continue;JSONObject p=new JSONObject(old.toString());p.remove("simulationId");p.put("id",id).put("clientLocalId","").put("pdvId",JSONObject.NULL).put("syncState","LOCAL_DRAFT").put("legacySource",source.getName()).put("budget",new JSONObject()).put("contract",new JSONObject()).put("createdAt",System.currentTimeMillis());list("projects").put(p);}catch(Exception ignored){/* Keep original files intact; report counts in UI, no overwriting. */}}data.put("legacyImported",true);save();}
}
